import axios from 'axios';

// Use /api via Nginx in prod, keep 3000 in dev if you want
const baseURL =
  process.env.REACT_APP_API_URL        // e.g. http://13.211.211.43/api
  || (process.env.NODE_ENV === 'production'
      ? 'http://13.211.211.43/api'
      : 'http://localhost:5001/api');  // dev fallback; change if needed

const instance = axios.create({ baseURL });
export default instance;
